import{_ as t,o as i,c as a,a0 as o}from"./chunks/framework.DzvPB4Y-.js";const h=JSON.parse('{"title":"Bin Types and Objectives","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/bpp3d/business-scenario.md","filePath":"frameworks/bpp3d/business-scenario.md"}'),n={name:"frameworks/bpp3d/business-scenario.md"};function s(r,e,c,l,d,p){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="bin-types-and-objectives" tabindex="-1">Bin Types and Objectives <a class="header-anchor" href="#bin-types-and-objectives" aria-label="Permalink to &quot;Bin Types and Objectives&quot;">​</a></h1><p>After <a href="./first-loading.html">your first 3D loading</a> connects final selection and packing analysis, introduce a second bin type. This exercise uses cubes so orientation complexity does not hide objective configuration.</p><h2 id="_1-a-scenario-that-separates-objectives" tabindex="-1">1. A Scenario That Separates Objectives <a class="header-anchor" href="#_1-a-scenario-that-separates-objectives" aria-label="Permalink to &quot;1. A Scenario That Separates Objectives&quot;">​</a></h2><p>Load ten <code>2 × 2 × 2 m</code> cubes, net volume 80 m³, with ample weight capacity and no extra spacing, support or balance rules:</p><table tabindex="0"><thead><tr><th>Type</th><th>Inner dimensions</th><th style="text-align:right;">Volume</th><th style="text-align:right;">Available bins</th><th style="text-align:right;">Cost per bin</th></tr></thead><tbody><tr><td>S</td><td>4 × 4 × 4 m</td><td style="text-align:right;">64 m³</td><td style="text-align:right;">2</td><td style="text-align:right;">4</td></tr><tr><td>L</td><td>4 × 4 × 6 m</td><td style="text-align:right;">96 m³</td><td style="text-align:right;">1</td><td style="text-align:right;">10</td></tr></tbody></table><p>S fits at most eight cubes. L fits twelve on a 2×2×3 grid, so one L or two S can carry demand. Consumed volume is 96 versus 128 m³; cost is 10 versus 8. Minimum count and volume favor L; minimum cost favors two S.</p><p>This is a new hand-checkable exercise, not a case automatically covered by the first-lesson baseline. Generated layers and final packing must actually contain the relevant feasible choices.</p><h2 id="_2-connect-three-multi-type-responsibilities" tabindex="-1">2. Connect Three Multi-Type Responsibilities <a class="header-anchor" href="#_2-connect-three-multi-type-responsibilities" aria-label="Permalink to &quot;2. Connect Three Multi-Type Responsibilities&quot;">​</a></h2><ol><li>Include every type in generation: Kotlin <code>Bpp3dLayerGenerationRequest.bins</code>; Rust <code>LayerGenerationRequest.bins</code>.</li><li>Retain originating bin type in column identity. Identical coordinates on different types are different layers.</li><li>Supply actual available final bins: Kotlin <code>finalBins</code>, and Rust&#39;s corresponding final-executor input. A type catalog does not mean unlimited physical bins; array indices should not become cross-request identities.</li></ol><p>Set exact demand to ten for the same item ID. Follow the first lesson&#39;s request factory to keep demand representations, seed columns and final bins consistent. A small bin&#39;s capacity of eight is not the order quantity.</p><h2 id="_3-configure-objectives-explicitly" tabindex="-1">3. Configure Objectives Explicitly <a class="header-anchor" href="#_3-configure-objectives-explicitly" aria-label="Permalink to &quot;3. Configure Objectives Explicitly&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Meaning</th><th>Kotlin field</th><th>Rust field</th></tr></thead><tbody><tr><td>Consumed volume weight</td><td><code>finalBinVolumeWeight</code></td><td><code>final_bin_volume_weight</code></td></tr><tr><td>Count coefficient</td><td><code>finalBinAmountCoefficient</code></td><td><code>final_bin_amount_coefficient</code></td></tr><tr><td>Type-cost weight</td><td><code>finalBinTypeCostWeight</code></td><td><code>final_bin_type_cost_weight</code></td></tr><tr><td>Type-cost map</td><td><code>finalBinTypeCosts</code></td><td><code>final_bin_type_costs</code></td></tr></tbody></table><p>See the <a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp3d/bpp3d-application/src/main/fuookami/ospf/kotlin/framework/bpp3d/application/service/ColumnGenerationStandardExecutors.kt" target="_blank" rel="noreferrer">Kotlin standard executors</a> and <a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp3d/src/application/service/executor/config.rs" target="_blank" rel="noreferrer">Rust executor configuration</a>. Current defaults are volume weight 1, count coefficient <code>1e-6</code> and cost weight 0. Filling the cost map alone does not make cost dominate.</p><p>First isolate pure volume and pure cost. Then set the count coefficient to zero and explore normalized <code>score = consumed_volume + λ × cost</code>: L scores <code>96 + 10λ</code>; two S score <code>128 + 8λ</code>. They tie at λ=16; larger λ reverses the preference. Volume numbers here use m³, so define the weight&#39;s conversion convention.</p><p>A weighted sum is not strict volume-first, cost-second optimization. Such a requirement needs proven bounded weights or an explicitly evaluated staged optimization that fixes the first optimum. Do not claim default <code>1e-6</code> guarantees lexicographic priority at every scale.</p><h2 id="_4-validate-packing-not-candidate-volume" tabindex="-1">4. Validate Packing, Not Candidate Volume <a class="header-anchor" href="#_4-validate-packing-not-candidate-volume" aria-label="Permalink to &quot;4. Validate Packing, Not Candidate Volume&quot;">​</a></h2><ul><li>Place exactly ten items without counting one item through multiple selected layers.</li><li>Validate bounds, overlap, orientations, weight and enabled support rules on actual placements.</li><li>Recompute actual bin count, 96/128 m³ consumption and cost; unused volume is 16/48 m³ respectively.</li><li>Check RMP/final extensions and backends, <code>finalSolved</code> or corresponding diagnostics, packing snapshots and placements together.</li></ul><p>Record objective coefficients separately from solve scope. Correct coefficients do not establish a complete candidate pool or global optimality of the new scenario.</p><p>If one item cannot fit, inspect orientation and generation first. If layers exist but final packing fails, inspect physical bins, demand and cross-layer geometry. Preserve original diagnostics using the <a href="./../integration.html">integration guide</a>, rather than only increasing iterations.</p><p>Repository regression commands live in <a href="./../verification.html">Verification</a>. Complete the business input, call and result checks before using them.</p>',20)])])}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
